import{_ as t,o as e,c as r,a0 as o}from"./chunks/framework.Caz7a20Z.js";const h=JSON.parse('{"title":"论文代码整理过半","description":"今天把论文代码整理了一大半，量实在太大，没 AI 真不敢想这是多大的工程，剩下的明天接着弄。","frontmatter":{"title":"论文代码整理过半","date":"2026-08-21T00:00:00.000Z","tags":["日记"],"description":"今天把论文代码整理了一大半，量实在太大，没 AI 真不敢想这是多大的工程，剩下的明天接着弄。"},"headers":[],"relativePath":"posts/diary-20260821.md","filePath":"posts/diary-20260821.md","lastUpdated":1787318906000}'),s={name:"posts/diary-20260821.md"};function i(p,a,n,d,l,_){return e(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="论文代码整理过半" tabindex="-1">论文代码整理过半 <a class="header-anchor" href="#论文代码整理过半" aria-label="Permalink to &quot;论文代码整理过半&quot;">​</a></h1><p>今天干了一件挺实在的事——整理论文里用到的代码。</p><p>忙活了一整天，总算把<strong>大概一半</strong>整理完了。说是&quot;整理&quot;，其实挺杂的：环境依赖要理顺、脚本要归类、跑出来的结果和图要对应上、注释和命名也得顺一遍，免得以后自己都看不懂。</p><h2 id="没有-ai-真的不敢想" tabindex="-1">没有 AI 真的不敢想 <a class="header-anchor" href="#没有-ai-真的不敢想" aria-label="Permalink to &quot;没有 AI 真的不敢想&quot;">​</a></h2><p>做到一半真的感慨：这工作量也太吓人了。</p><p>如果只是零散几段还好，可论文背后的代码是一整套——数据处理、实验、画图、对比……环环相扣。要是没有 AI 帮着快速读懂旧代码、批量重命名、生成说明和重构建议，光是理清这些、把重复的东西合并掉，估计得耗掉我好几倍的时间，还未必能理得这么清楚。</p><p>说真的，<strong>没有 AI 我根本不敢想象这是多大的工作量</strong>。它不是替我做了决定，而是把那些机械、繁琐、容易出错的活儿扛了下来，让我能把精力放在&quot;怎么组织才合理&quot;上面。</p><h2 id="剩下的留给明天" tabindex="-1">剩下的留给明天 <a class="header-anchor" href="#剩下的留给明天" aria-label="Permalink to &quot;剩下的留给明天&quot;">​</a></h2><p>今天到这儿也差不多了，眼睛和脑子都有点转不动。</p><p>剩下那一半不急着今晚硬赶——强行熬夜容易越理越乱，明天状态好点一次性收尾反而快。先记一笔：明天继续把后半部分收掉，争取这周内把整套代码收拾干净。</p><p>今天进度过半，算是个还不错的交代。睡了。</p>',11)])])}const u=t(s,[["render",i]]);export{h as __pageData,u as default};
